files.examples/02.js:
// Partly fits. Changes from the example:
//  - the CSV source declares its columns as text; there is no file reader, so types come from cast.
//  - units: "int" is refused by the cast shape (B004); there is no integer type, so it is cast to f64.
//  - dropNulls is not written: the type system has no nullable column to narrow.
import { program } from "../data.grammar.js";

export default program("clean-sales")
  .source("raw", { date: "str", region: "str", units: "str", "Unit Price": "str" })
  .table("sales", "raw")
    .rename("Unit Price", "price")
    .cast("date", "date")
    .cast("units", "f64")
    .cast("price", "f64")
    .trim("region")
    .replace("region", { "N.": "North", "S.": "South" })
    .dedupe("date", "region")
    .derive("revenue", row => row.units * row.price);

files.examples/03.js:
// Partly fits. Changes from the example:
//  - wb.select with a data-driven option list (from: t => ...) is a build-time lambda: refused; region is a plain value.
//  - wb.date({ value: "2026-01-01" }) becomes milliseconds, since there is no date literal.
//  - .view(...) renders and is refused (R8).
import { program } from "../data.grammar.js";

export default program("filters")
  .source("sales", { date: "date", region: "str", units: "f64", price: "f64" })
  .param("minUnits", { value: 50, min: 0, max: 500, step: 10 })
  .param("region", { value: "All" })
  .param("since", { date: 1767225600000 })
  .table("picked", "sales")
    .filter(row => row.units >= $.minUnits)
    .filter(row => $.region === "All" || row.region === $.region)
    .filter(row => row.date >= $.since);

files.examples/04.js:
// Partly fits. The table is the whole of it. The chart and the view render and are refused (R8);
// the chart's runtime lambda, .y(() => $.metric), has no target here.
import { program } from "../data.grammar.js";

export default program("revenue-by-month")
  .source("sales", { date: "date", region: "str", units: "f64", price: "f64" })
  .param("metric", { value: "revenue", options: ["revenue", "units"] })
  .table("monthly", "sales")
    .derive("revenue", row => row.units * row.price)
    .derive("month", row => truncMonth(row.date))
    .groupBy("month", "region")
    .agg({
      revenue: g => g.sum("revenue"),
      units: g => g.sum("units"),
      orders: g => g.count(),
    })
    .sort("month");

